EXTRA = [
 ("INS01", "NEGATION", 1, "The insurer will pay for loss or damage even if, at the time of the accident, the vehicle was driven by someone without a valid driving licence.", "यदि दुर्घटना के समय वाहन ऐसा व्यक्ति चला रहा था जिसके पास वैध ड्राइविंग लाइसेंस नहीं था, तब भी बीमाकर्ता हानि या क्षति का भुगतान करेगा।"),
 ("INS01", "DATE", 3, "The insurer will not pay for loss or damage if the vehicle was driven by someone who did not have a valid driving licence at the time the policy was bought.", "यदि वाहन ऐसा व्यक्ति चला रहा था जिसके पास पॉलिसी खरीदते समय वैध ड्राइविंग लाइसेंस नहीं था, तो बीमाकर्ता हानि या क्षति का भुगतान नहीं करेगा।"),
 ("INS02", "ENTITY", 2, "The insurer must inform you in writing within seven days of an accident. If this is not done, the claim may be rejected.", "बीमाकर्ता को दुर्घटना के सात दिनों के भीतर आपको लिखित सूचना देनी होगी। ऐसा न होने पर दावा अस्वीकार किया जा सकता है।"),
 ("INS02", "MODALITY", 3, "You must inform the insurer in writing within seven days of an accident. If you do not, the insurer must reject the claim.", "आपको दुर्घटना के सात दिनों के भीतर बीमाकर्ता को लिखित सूचना देनी होगी। ऐसा न करने पर बीमाकर्ता को दावा अस्वीकार करना ही होगा।"),
 ("INS03", "SCOPE", 3, "All illnesses are covered only after 48 months of continuous cover from the start of your first policy.", "सभी बीमारियाँ आपकी पहली पॉलिसी शुरू होने से 48 महीने के निरंतर कवर के बाद ही कवर होंगी।"),
 ("INS03", "OMIT_COND", 4, "Illnesses you had before buying the policy are covered only after 48 months of cover from the start of your first policy.", "पॉलिसी लेने से पहले की बीमारियाँ आपकी पहली पॉलिसी शुरू होने से 48 महीने के कवर के बाद ही कवर होंगी।"),
 ("INS04", "DATE", 3, "The insurer can cancel the policy for misrepresentation or fraud by sending you five days' written notice by registered post to your last known address.", "गलत जानकारी या धोखाधड़ी होने पर बीमाकर्ता आपके अंतिम ज्ञात पते पर पंजीकृत डाक से पाँच दिन का लिखित नोटिस भेजकर पॉलिसी रद्द कर सकता है।"),
 ("INS04", "MINOR", 6, "The insurer can cancel the policy for misrepresentation or fraud by sending you fifteen days' written notice to your last known address.", "गलत जानकारी या धोखाधड़ी होने पर बीमाकर्ता आपके अंतिम ज्ञात पते पर पंद्रह दिन का लिखित नोटिस भेजकर पॉलिसी रद्द कर सकता है।"),
 ("INS05", "OMIT_COND", 4, "Hospital costs are paid only if you stay in hospital for at least 24 hours. This rule does not apply to the day-care procedures listed in Annexure II.", "अस्पताल का खर्च तभी मिलेगा जब आप कम से कम 24 घंटे भर्ती रहें। यह नियम अनुलग्नक II में दी गई डे-केयर प्रक्रियाओं पर लागू नहीं होता।"),
 ("INS05", "MINOR", 6, "Hospital costs are paid only if you stay in hospital for at least 24 hours in a row. This rule does not apply to the day-care procedures listed in the annexure.", "अस्पताल का खर्च तभी मिलेगा जब आप लगातार कम से कम 24 घंटे भर्ती रहें। यह नियम अनुलग्नक में दी गई डे-केयर प्रक्रियाओं पर लागू नहीं होता।"),
 ("INS06", "HALLUC", 3, "The policy does not pay for damage to the insured property caused by normal wear and tear, slow deterioration, or built-in defects, and you must repair such damage within 30 days to keep your cover.", "सामान्य टूट-फूट, धीरे-धीरे होने वाली खराबी या बनावटी दोष से बीमित संपत्ति को हुई क्षति का भुगतान पॉलिसी नहीं करती, और कवर बनाए रखने के लिए आपको ऐसी क्षति की मरम्मत 30 दिनों के भीतर करानी होगी।"),
 ("INS06", "EXC_REMOVED", 3, "The policy does not pay for damage to the insured property caused by normal wear and tear or slow deterioration.", "सामान्य टूट-फूट या धीरे-धीरे होने वाली खराबी से बीमित संपत्ति को हुई क्षति का भुगतान पॉलिसी नहीं करती।"),
 ("INS07", "NUMBER", 2, "If the vehicle is a total loss, the insurer will pay half of its Insured Declared Value minus the compulsory deductible.", "यदि वाहन पूरी तरह नष्ट हो जाए, तो बीमाकर्ता अनिवार्य कटौती घटाकर उसके बीमित घोषित मूल्य का आधा देगा।"),
 ("INS07", "MODALITY", 2, "If the vehicle is a total loss, the insurer may pay its Insured Declared Value minus the compulsory deductible.", "यदि वाहन पूरी तरह नष्ट हो जाए, तो बीमाकर्ता अनिवार्य कटौती घटाकर उसका बीमित घोषित मूल्य दे सकता है।"),
 ("INS08", "EXC_REMOVED", 3, "You can renew within 30 days after the policy ends and keep your continuity benefits.", "आप पॉलिसी खत्म होने के 30 दिनों के भीतर नवीनीकरण कराकर निरंतरता लाभ बनाए रख सकते हैं।"),
 ("INS08", "DATE", 3, "You can renew within 15 days after the policy ends and keep your continuity benefits, but you are not covered during those 15 days.", "आप पॉलिसी खत्म होने के 15 दिनों के भीतर नवीनीकरण कराकर निरंतरता लाभ बनाए रख सकते हैं, लेकिन इन 15 दिनों में आपको कवर नहीं मिलेगा।"),
 ("INS09", "DATE", 3, "Send your reimbursement claim with the original bills, discharge summary and test reports within 30 days after leaving hospital.", "अस्पताल से छुट्टी के 30 दिनों के भीतर मूल बिल, डिस्चार्ज सारांश और जाँच रिपोर्ट के साथ अपना प्रतिपूर्ति दावा भेजें।"),
 ("INS09", "ENTITY", 3, "The hospital will send your reimbursement claim with the original bills, discharge summary and test reports within 15 days after you leave hospital.", "अस्पताल से छुट्टी के 15 दिनों के भीतर अस्पताल मूल बिल, डिस्चार्ज सारांश और जाँच रिपोर्ट के साथ आपका प्रतिपूर्ति दावा भेजेगा।"),
 ("INS10", "NEGATION", 1, "The insurer will not cover your legal liability if the use of your insured vehicle causes the death of or injury to another person.", "यदि आपके बीमित वाहन के उपयोग से किसी अन्य व्यक्ति की मृत्यु या चोट होती है, तो बीमाकर्ता आपके कानूनी दायित्व को कवर नहीं करेगा।"),
 ("INS10", "HALLUC", 3, "The insurer will cover your legal liability if the use of your insured vehicle causes the death of or injury to another person, but only if you report it to the police within 24 hours.", "यदि आपके बीमित वाहन के उपयोग से किसी अन्य व्यक्ति की मृत्यु या चोट होती है, तो बीमाकर्ता आपके कानूनी दायित्व को कवर करेगा, लेकिन केवल तभी जब आप 24 घंटे के भीतर पुलिस को इसकी सूचना दें।"),
 ("INS11", "NUMBER", 3, "Maternity costs are paid after a nine-month waiting period from the start of the policy, for at most three deliveries in the policyholder's lifetime.", "मातृत्व खर्च पॉलिसी शुरू होने से नौ महीने की प्रतीक्षा अवधि के बाद मिलेगा, और पॉलिसीधारक के जीवन में अधिकतम तीन प्रसवों के लिए ही मिलेगा।"),
 ("INS11", "DATE", 2, "Maternity costs are paid after a three-month waiting period from the start of the policy, for at most two deliveries in the policyholder's lifetime.", "मातृत्व खर्च पॉलिसी शुरू होने से तीन महीने की प्रतीक्षा अवधि के बाद मिलेगा, और पॉलिसीधारक के जीवन में अधिकतम दो प्रसवों के लिए ही मिलेगा।"),
 ("INS12", "MODALITY", 3, "The company may refuse to pay any claim that is fraudulent in any way or supported by fraudulent means.", "जो दावा किसी भी तरह से धोखाधड़ी वाला है या धोखाधड़ी के साधनों से समर्थित है, कंपनी उसका भुगतान करने से मना कर सकती है।"),
 ("INS12", "SCOPE", 3, "The company will not pay any claim that is wholly fraudulent or supported by fraudulent means.", "जो दावा पूरी तरह से धोखाधड़ी वाला है या धोखाधड़ी के साधनों से समर्थित है, कंपनी उसका भुगतान नहीं करेगी।"),
 ("INS13", "NUMBER", 2, "If you have more than one policy covering the same risk, this insurer pays only half of the loss.", "यदि एक ही जोखिम के लिए आपके पास एक से अधिक पॉलिसियाँ हैं, तो यह बीमाकर्ता हानि का केवल आधा हिस्सा देगा।"),
 ("INS13", "OMIT_COND", 3, "If you have more than one policy, this insurer pays only its proportionate share of the loss.", "यदि आपके पास एक से अधिक पॉलिसियाँ हैं, तो यह बीमाकर्ता हानि का केवल अपना अनुपातिक हिस्सा देगा।"),
 ("INS14", "SCOPE", 3, "A deductible of Rs. 5,000 applies to every claim made under this policy.", "इस पॉलिसी के तहत हर दावे पर 5,000 रुपये की कटौती लागू होती है।"),
 ("INS14", "HALLUC", 3, "A deductible of Rs. 5,000 applies to every claim made under Section I of this policy, and an extra processing fee is charged on each claim.", "इस पॉलिसी की धारा I के तहत हर दावे पर 5,000 रुपये की कटौती लागू होती है, और हर दावे पर अतिरिक्त प्रोसेसिंग शुल्क भी लिया जाता है।"),
 ("INS15", "ENTITY", 2, "The insurer must take reasonable care to protect the insured property, and you cannot simply leave the property to the insurer.", "बीमाकर्ता को बीमित संपत्ति की उचित देखभाल करनी होगी, और आप संपत्ति को बीमाकर्ता के भरोसे यूँ ही नहीं छोड़ सकते।"),
 ("INS15", "NEGATION", 2, "You must take reasonable care to protect the insured property, but you can simply leave the property to the insurer.", "आपको बीमित संपत्ति की उचित देखभाल करनी होगी, लेकिन आप संपत्ति को बीमाकर्ता के भरोसे यूँ ही छोड़ सकते हैं।"),
 ("INS16", "OMIT_COND", 3, "Cashless treatment is available only at network hospitals.", "कैशलेस इलाज केवल नेटवर्क अस्पतालों में मिलता है।"),
 ("INS16", "ENTITY", 3, "Cashless treatment is available only at network hospitals and only after the hospital approves it in advance.", "कैशलेस इलाज केवल नेटवर्क अस्पतालों में मिलता है, और वह भी अस्पताल की पहले से मंज़ूरी मिलने के बाद।"),
 ("INS17", "NEGATION", 1, "You do not lose your No Claim Bonus if you make a claim during the policy period, except when the claim is only for stolen accessories.", "पॉलिसी अवधि में दावा करने पर आपका नो क्लेम बोनस खत्म नहीं होगा, सिवाय तब जब दावा केवल चोरी हुए सहायक उपकरणों के लिए हो।"),
 ("INS17", "MINOR", 6, "You lose your No Claim Bonus if you make a claim, except when the claim is only for stolen accessories.", "दावा करने पर आपका नो क्लेम बोनस खत्म हो जाएगा, सिवाय तब जब दावा केवल चोरी हुए सहायक उपकरणों के लिए हो।"),
 ("INS18", "ENTITY", 3, "If you accept liability but there is a disagreement about the amount of the loss, the dispute will go to arbitration.", "यदि आप दायित्व स्वीकार करते हैं लेकिन हानि की राशि पर असहमति है, तो विवाद मध्यस्थता में जाएगा।"),
 ("INS18", "MODALITY", 3, "If the insurer accepts liability but there is a disagreement about the amount of the loss, the dispute may go to arbitration.", "यदि बीमाकर्ता दायित्व स्वीकार करता है लेकिन हानि की राशि पर असहमति है, तो विवाद मध्यस्थता में जा सकता है।"),
 ("INS19", "MODALITY", 2, "After a claim is paid, the sum insured goes down by that amount. You must restore it by paying an extra premium.", "दावे का भुगतान होने के बाद बीमा राशि उतनी कम हो जाती है। आपको अतिरिक्त प्रीमियम देकर इसे बहाल करना होगा।"),
 ("INS19", "NUMBER", 2, "After a claim is paid, the sum insured goes down by twice that amount. You can restore it by paying an extra premium.", "दावे का भुगतान होने के बाद बीमा राशि दावे की दोगुनी राशि जितनी कम हो जाती है। अतिरिक्त प्रीमियम देकर आप इसे बहाल कर सकते हैं।"),
 ("INS20", "HALLUC", 3, "Whenever the insurer reasonably asks, you must have a medical check-up, at your own cost, by a doctor the insurer chooses.", "जब भी बीमाकर्ता उचित रूप से कहे, आपको अपने खर्च पर बीमाकर्ता द्वारा चुने गए डॉक्टर से मेडिकल जाँच करानी होगी।"),
 ("INS20", "MINOR", 5, "Whenever the insurer asks, you must have a medical check-up by a doctor the insurer chooses.", "जब भी बीमाकर्ता कहे, आपको बीमाकर्ता द्वारा चुने गए डॉक्टर से मेडिकल जाँच करानी होगी।"),
]
